function computePrice(item: any) {
  switch (item.type) {
    case 'book':
      return item.pages * 0.5;
    case 'membership':
      return 20;
    case 'digital':
      return 5 + item.sizeMb * 0.01;
    default:
      throw new Error('Unknown type');
  }
}

interface Payment { method: string; amount: number }
function process(payment: Payment) {
  switch (payment.method) {
    case 'card':
      return chargeCard(payment.amount);
    case 'paypal':
      return chargePaypal(payment.amount);
    case 'wire':
      return chargeWire(payment.amount);
    default:
      throw new Error('Unsupported method');
  }
}

