class PaypalChanger implements Changer { charge(a:number){ return a * 1.03 } }

// Version B: centralized conditional
function process(payment: Payment){
  switch(payment.method){
    case 'card': return chargeCard(payment.amount)
    case 'paypal': return chargePaypal(payment.amount)
    default: throw new Error('Unsupported')
  }
}
